import{b as a,O as t,g as i,j as e}from"./chunks/framework.DSt9LnBW.js";const k=JSON.parse('{"title":"安装与环境准备","description":"","frontmatter":{},"headers":[],"relativePath":"performance/locust/intro/setup/index.md","filePath":"性能测试/2.Locust/1.入门篇/02.安装与环境准备.md","lastUpdated":1789911840000}'),n={name:"performance/locust/intro/setup/index.md"};function p(o,s,l,d,h,c){return t(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="安装与环境准备" tabindex="-1">安装与环境准备 <a class="header-anchor" href="#安装与环境准备" aria-label="Permalink to &quot;安装与环境准备&quot;">​</a></h1><blockquote><p>十分钟装好 Locust，顺手把项目和目录结构立起来。装不上的常见原因也一并说清。</p></blockquote><h2 id="前置条件-python-3-11-及以上" tabindex="-1">前置条件：Python 3.11 及以上 <a class="header-anchor" href="#前置条件-python-3-11-及以上" aria-label="Permalink to &quot;前置条件：Python 3.11 及以上&quot;">​</a></h2><p>Locust 2.46 要求 <strong>Python ≥ 3.11</strong>（<a href="https://pypi.org/project/locust/" target="_blank" rel="noreferrer">PyPI 页面</a> 有写）。先确认版本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Python 3.11.9    ← 3.11 及以上都可以</span></span></code></pre></div><table tabindex="0"><thead><tr><th>输出</th><th>怎么办</th></tr></thead><tbody><tr><td><code>Python 3.11.x</code> / <code>3.12.x</code> / <code>3.13.x</code></td><td>直接下一步</td></tr><tr><td><code>Python 3.9.x</code> 及更低</td><td>先升级 Python（macOS 用 <code>brew install python@3.12</code>）</td></tr><tr><td><code>command not found: python3</code></td><td>还没装 Python，去 <a href="https://www.python.org/downloads/" target="_blank" rel="noreferrer">https://www.python.org/downloads/</a> 装</td></tr></tbody></table><blockquote><p>不确定系统里有几个 Python 时，用 <code>python3 -m pip --version</code> 看 pip 挂在哪个解释器上，避免&quot;装了却用不了&quot;。</p></blockquote><h2 id="为什么要用虚拟环境" tabindex="-1">为什么要用虚拟环境 <a class="header-anchor" href="#为什么要用虚拟环境" aria-label="Permalink to &quot;为什么要用虚拟环境&quot;">​</a></h2><p>直接 <code>pip install locust</code> 装到系统 Python 里，容易和系统自带的包打架，有些系统（如 macOS 的 Homebrew Python）还会直接拒绝安装。</p><p>虚拟环境给项目单独一套依赖，用完删掉即可：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locust-demo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locust-demo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 激活（macOS / Linux）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 激活（Windows）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .venv\\Scripts\\activate</span></span></code></pre></div><p>激活成功后命令行前面会出现 <code>(.venv)</code>。之后所有 <code>pip</code> 和 <code>locust</code> 命令都只作用于这个环境。</p><blockquote><p>每次新开终端都要重新 <code>source .venv/bin/activate</code>，忘了会提示找不到 <code>locust</code> 命令。</p></blockquote><h2 id="安装-locust" tabindex="-1">安装 Locust <a class="header-anchor" href="#安装-locust" aria-label="Permalink to &quot;安装 Locust&quot;">​</a></h2><h3 id="方式一-pip-安装-推荐" tabindex="-1">方式一：pip 安装（推荐） <a class="header-anchor" href="#方式一-pip-安装-推荐" aria-label="Permalink to &quot;方式一：pip 安装（推荐）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locust</span></span></code></pre></div><h3 id="方式二-uvx-免安装试用" tabindex="-1">方式二：uvx 免安装试用 <a class="header-anchor" href="#方式二-uvx-免安装试用" aria-label="Permalink to &quot;方式二：uvx 免安装试用&quot;">​</a></h3><p>如果只想快速跑一遍、不想装环境，用 <a href="https://docs.astral.sh/uv/" target="_blank" rel="noreferrer">uv</a>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uvx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -V</span></span></code></pre></div><p><code>uvx</code> 会把 Locust 装在一个临时环境里运行，用完不污染本机。</p><h3 id="方式三-预发布版-一般用不到" tabindex="-1">方式三：预发布版（一般用不到） <a class="header-anchor" href="#方式三-预发布版-一般用不到" aria-label="Permalink to &quot;方式三：预发布版（一般用不到）&quot;">​</a></h3><p>想用还没正式发布的新特性：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --pre</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locust</span></span></code></pre></div><blockquote><p>预发布版每次合并代码就发一个，<strong>不建议</strong>用在正式压测里，行为可能随时变。</p></blockquote><h3 id="国内网络慢怎么办" tabindex="-1">国内网络慢怎么办 <a class="header-anchor" href="#国内网络慢怎么办" aria-label="Permalink to &quot;国内网络慢怎么办&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://pypi.tuna.tsinghua.edu.cn/simple</span></span></code></pre></div><h2 id="验证安装" tabindex="-1">验证安装 <a class="header-anchor" href="#验证安装" aria-label="Permalink to &quot;验证安装&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">locust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -V</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># locust 2.46.6 from /path/to/.venv/lib/python3.12/site-packages/locust (Python 3.12.5)</span></span></code></pre></div><p>看到版本号和 Python 路径就成功了。</p><blockquote><p>顺手看一眼 <code>locust --help</code>，后面命令行篇讲的参数都在这。不用背，混个眼熟。</p></blockquote><h2 id="装一次-换个项目还能用吗" tabindex="-1">装一次，换个项目还能用吗 <a class="header-anchor" href="#装一次-换个项目还能用吗" aria-label="Permalink to &quot;装一次，换个项目还能用吗&quot;">​</a></h2><p>上面 <code>locust -V</code> 输出里那串路径，其实回答了这个问题：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>locust 2.46.6 from /path/to/locust-demo/.venv/lib/python3.12/site-packages/locust</span></span>
<span class="line"><span>                 ^^^^^^^^^^^^^^^^^^^^^^^^^^^^</span></span>
<span class="line"><span>                 装在这个 venv 里，不是全局</span></span></code></pre></div><p><strong>venv 没有&quot;全局&quot;这个说法，它就是一个装了依赖的普通目录。</strong> 换到别的项目目录，如果没 <code>source</code> 这个 venv，<code>locust</code> 命令就找不到了——这正是新手最常见的&quot;昨天还能用，今天 <code>command not found</code>&quot;。</p><p>想一次装好、多个项目都能用，有两条路。</p><h3 id="方案一-pipx-轻量脚本推荐" tabindex="-1">方案一：pipx（轻量脚本推荐） <a class="header-anchor" href="#方案一-pipx-轻量脚本推荐" aria-label="Permalink to &quot;方案一：pipx（轻量脚本推荐）&quot;">​</a></h3><p>Locust 是<strong>命令行工具</strong>，不是被你的代码 <code>import</code> 的库（不像 <code>requests</code> 那样要在项目里声明依赖），用 <a href="https://pipx.pypa.io/" target="_blank" rel="noreferrer">pipx</a> 装很省事：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pipx</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pipx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ensurepath</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 把 pipx 的目录加进 PATH，重开终端生效</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pipx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locust</span></span></code></pre></div><p>之后<strong>任何目录、任何项目</strong>里 <code>locust</code> 都能直接用，而且它跑在自己的独立环境里，不污染系统 Python。</p><blockquote><p>pipx 和 <code>pip install</code> 的区别：pipx 给每个工具单独建一个 venv，只把可执行命令暴露到 PATH。所以它既有&quot;全局可用&quot;的方便，又有&quot;互不干扰&quot;的干净——装多个版本的工具也不打架。</p><p>Windows 上用 <code>pip install --user pipx</code> + <code>python -m pipx ensurepath</code> 也能同样操作。</p></blockquote><p><strong>但脚本里能 import 什么，由 pipx 说了算。</strong> pipx 的环境是<strong>封闭</strong>的——官方原话是它&quot;只用自己隔离环境里的依赖，绝不碰系统或项目的 site-packages&quot;。所以：</p><table tabindex="0"><thead><tr><th>脚本里的 import</th><th>pipx 方式能用吗</th></tr></thead><tbody><tr><td><code>from locust import HttpUser, task, between</code></td><td>能，Locust 自带</td></tr><tr><td><code>import requests</code>、<code>gevent</code></td><td>能，是 Locust 的依赖，跟着装进来了</td></tr><tr><td><code>from common import auth</code>（你自己的模块）</td><td>能，Locust 会把当前目录加进 <code>sys.path</code></td></tr><tr><td><code>import pandas</code>（分析报告）</td><td><strong>不能</strong>，<code>ModuleNotFoundError</code></td></tr><tr><td><code>import faker</code>（造测试数据）</td><td><strong>不能</strong></td></tr><tr><td><code>import jwt</code>（登录态）</td><td><strong>不能</strong></td></tr></tbody></table><p>注意第三行：<strong>你自己的本地模块没问题，挂的是第三方包</strong>——所以报错信息有时挺迷惑（&quot;我的 <code>common/auth.py</code> 明明在，怎么 pandas 找不到&quot;）。</p><p>要用第三方包，得把它们&quot;注入&quot;进去：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pipx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inject</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pandas</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> faker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pyjwt</span></span></code></pre></div><p><strong>代价是注入的包全局共享</strong>：所有用到这个 <code>locust</code> 命令的项目，共用同一份 pandas / faker。于是</p><ul><li>项目 A 要 <code>faker 19.x</code>、项目 B 要 <code>faker 30.x</code> → <strong>没法同时满足</strong></li><li>随手敲个 <code>pipx upgrade --include-injected locust</code>，所有项目的依赖一起变，某个脚本可能就崩了</li></ul><p>所以 <strong>pipx 适合&quot;脚本很轻&quot;的场景</strong>（只 import locust 和 requests）。一旦脚本开始要 pandas、faker 这类库——进阶篇讲&quot;测试数据&quot;时就会用到——就该回到项目自己的 venv。</p><h3 id="方案二-共享-venv" tabindex="-1">方案二：共享 venv <a class="header-anchor" href="#方案二-共享-venv" aria-label="Permalink to &quot;方案二：共享 venv&quot;">​</a></h3><p>不想引入新工具，就把 venv 建在家目录下，当成一个&quot;压测专用环境&quot;：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/venvs/locust</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 用的时候激活它——在哪个项目目录下都行</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/venvs/locust/bin/activate</span></span></code></pre></div><p>好处是压测相关的东西（Locust、分析报告用的 pandas 等）都放一起，换项目不用重装。</p><h3 id="到底用哪个" tabindex="-1">到底用哪个 <a class="header-anchor" href="#到底用哪个" aria-label="Permalink to &quot;到底用哪个&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>用哪个</th></tr></thead><tbody><tr><td>跟着本教程学，就一个 demo 目录</td><td>项目内 venv，简单直接</td></tr><tr><td>脚本只 import locust 和 requests</td><td><strong>pipx</strong></td></tr><tr><td>脚本要用 pandas / faker 等第三方库</td><td>项目内 venv + <code>requirements.txt</code></td></tr><tr><td>多个项目的依赖版本还不一样</td><td>项目内 venv</td></tr><tr><td>压测脚本要交给同事复现</td><td>项目内 venv + <code>requirements.txt</code></td></tr><tr><td>只想快速跑一次看看</td><td><code>uvx locust</code>（见上文方式二）</td></tr></tbody></table><blockquote><p><strong>pipx 和共享 venv 有一个共同的短板</strong>：它们是&quot;全局一份&quot;，跨项目共享依赖。脚本一多、依赖一杂，就容易出现版本冲突，或者变成一个&quot;什么都往里塞&quot;的杂物间——哪天某个包升级把 Locust 搞坏了也不好排查。</p><p>所以判断标准很简单：<strong>依赖跟着项目走（项目内 venv + <code>requirements.txt</code>）永远是能复现、能交付的那条路。</strong> pipx 和共享 venv 只在你确定&quot;脚本很轻、就图个方便&quot;时用。</p></blockquote><h3 id="装重了-确认在用的是哪一个" tabindex="-1">装重了：确认在用的是哪一个 <a class="header-anchor" href="#装重了-确认在用的是哪一个" aria-label="Permalink to &quot;装重了：确认在用的是哪一个&quot;">​</a></h3><p>如果你<strong>同时</strong>留了项目 venv 和 pipx 两套，谁生效取决于有没有激活 venv：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locust-demo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">which</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locust</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # → .venv/bin/locust     venv 激活时它排 PATH 最前</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deactivate</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">which</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locust</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # → ~/.local/bin/locust  pipx 的</span></span></code></pre></div><p><strong>能用的包也跟着切换</strong>，所以&quot;明明装了 pandas，怎么还报找不到&quot;时，先查这个：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">which</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locust</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 确认在用的是哪个</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">locust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -V</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 输出里的 site-packages 路径能看出是哪个环境</span></span></code></pre></div><h2 id="项目目录怎么放" tabindex="-1">项目目录怎么放 <a class="header-anchor" href="#项目目录怎么放" aria-label="Permalink to &quot;项目目录怎么放&quot;">​</a></h2><p>压测脚本就是 Python 文件，可以放在项目任意位置。推荐按下面结构组织，后面章节会往这个骨架里填东西：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>locust-demo/</span></span>
<span class="line"><span>├── .venv/                  # 虚拟环境，不要提交到 git</span></span>
<span class="line"><span>├── locustfile.py           # 压测脚本（Locust 默认找这个名字）</span></span>
<span class="line"><span>├── data/                   # 测试数据，如 users.csv</span></span>
<span class="line"><span>├── reports/                # 压测报告输出（CSV / HTML）</span></span>
<span class="line"><span>└── requirements.txt        # 依赖清单</span></span></code></pre></div><p>两个约定：</p><ul><li><strong>文件名默认 <code>locustfile.py</code></strong>。用别的名字也行，启动时用 <code>-f</code> 指定，比如 <code>locust -f perf/login.py</code>。</li><li><strong>多个脚本之间可以 <code>import</code></strong>。Locust 会把当前工作目录加入 <code>sys.path</code>，所以 <code>from common import login</code> 这种写法能直接用——这正是 Locust 比 JMeter 好用的地方。</li></ul><p>记录依赖，方便换机器复现：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> freeze</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> requirements.txt</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 换机器：pip install -r requirements.txt</span></span></code></pre></div><h3 id="脚本多起来之后" tabindex="-1">脚本多起来之后 <a class="header-anchor" href="#脚本多起来之后" aria-label="Permalink to &quot;脚本多起来之后&quot;">​</a></h3><p>一个 <code>locustfile.py</code> 写到几百行就该拆了。官方推荐按 Python 工程惯例组织——把公共逻辑抽成包，脚本分目录放：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>locust-demo/</span></span>
<span class="line"><span>├── common/                     # 公共代码（包）</span></span>
<span class="line"><span>│   ├── __init__.py</span></span>
<span class="line"><span>│   ├── auth.py                 # 登录、取 token</span></span>
<span class="line"><span>│   └── config.py               # 环境地址、账号等配置</span></span>
<span class="line"><span>├── my_locustfiles/             # 多个压测脚本</span></span>
<span class="line"><span>│   ├── api.py</span></span>
<span class="line"><span>│   └── website.py</span></span>
<span class="line"><span>├── data/</span></span>
<span class="line"><span>├── reports/</span></span>
<span class="line"><span>└── requirements.txt</span></span></code></pre></div><p>脚本里正常 <code>import</code> 就行：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># my_locustfiles/api.py</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> common.auth</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> common.config </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> HOST</span></span></code></pre></div><p>启动时用 <code>-f</code> 指到具体脚本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">locust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_locustfiles/api.py</span></span></code></pre></div><blockquote><p>关键点只有一个：<strong><code>locustfile.py</code> 就是个普通 Python 模块</strong>，工作目录会自动进 <code>sys.path</code>，所以 <code>import</code> 规则和写普通 Python 程序完全一样。拆不拆、怎么拆，按你项目的习惯来就行。</p></blockquote><h2 id="编辑器准备" tabindex="-1">编辑器准备 <a class="header-anchor" href="#编辑器准备" aria-label="Permalink to &quot;编辑器准备&quot;">​</a></h2><p>官方有一个 <strong>VS Code 扩展</strong>，可以侧边栏直接跑 Locust 脚本，调试时省去切终端：</p><ul><li>扩展市场搜 <code>Locust</code>（官方 ID：<code>locustio.locust</code>）</li><li>官方说明：<a href="https://docs.locust.io/en/stable/vscode-extension.html" target="_blank" rel="noreferrer">https://docs.locust.io/en/stable/vscode-extension.html</a></li></ul><blockquote><p>PyCharm / VS Code 直接跑 Python 脚本也行，Locust 提供了 <code>run_single_user()</code> 入口，进阶篇会讲。</p></blockquote><h2 id="装不上怎么办" tabindex="-1">装不上怎么办 <a class="header-anchor" href="#装不上怎么办" aria-label="Permalink to &quot;装不上怎么办&quot;">​</a></h2><p>按报错对照查：</p><table tabindex="0"><thead><tr><th>现象</th><th>原因</th><th>解决</th></tr></thead><tbody><tr><td><code>command not found: locust</code></td><td>虚拟环境没激活，或 <code>~/.local/bin</code> 不在 PATH</td><td>重新 <code>source .venv/bin/activate</code>；或改用 <code>python3 -m locust</code></td></tr><tr><td><code>error: externally-managed-environment</code></td><td>直接往系统 Python 装（PEP 668 保护）</td><td>建虚拟环境，别对抗系统</td></tr><tr><td><code>Permission denied</code></td><td>装到了系统目录</td><td>用虚拟环境，或加 <code>--user</code></td></tr><tr><td>装完 <code>locust -V</code> 报 <code>ModuleNotFoundError</code></td><td>pip 和 python 不是同一个解释器</td><td>统一用 <code>python3 -m pip install locust</code></td></tr><tr><td>卡在下载不动</td><td>网络问题</td><td>换国内镜像源</td></tr><tr><td><code>gevent</code> 编译失败</td><td>缺少编译工具（老版本 Python 才常见）</td><td>升级 Python 到 3.11+，官方已提供预编译包</td></tr></tbody></table><blockquote><p>已经装了 Locust 但版本旧（<code>locust -V</code> 显示 2.3x），直接 <code>pip install -U locust</code> 升级。本教程按 <strong>2.46.6</strong> 写，差异较大的地方会单独标注。</p></blockquote><h2 id="压高并发前-先看看文件描述符上限" tabindex="-1">压高并发前：先看看文件描述符上限 <a class="header-anchor" href="#压高并发前-先看看文件描述符上限" aria-label="Permalink to &quot;压高并发前：先看看文件描述符上限&quot;">​</a></h2><p>这一节属于&quot;现在用不上，压高并发时一定会踩&quot;，先留个印象。</p><p>Locust 的每个用户连接都会占用一个<strong>文件描述符</strong>（file descriptor）。操作系统默认的上限通常很小（macOS 常见 256），用户一多就会撞墙——现象是<strong>并发压不上去、日志里出现关于文件描述符的警告</strong>，而不是报错崩溃，很容易误判成&quot;被测服务到瓶颈了&quot;。</p><p>先看当前上限：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ulimit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span></span></code></pre></div><p>Locust 会尝试自动调高，但多数系统不允许（会有 warning）。手动调整：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># macOS / Linux：当前会话临时生效</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ulimit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 65535</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 然后再启动 Locust</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">locust</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locustfile.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --headless</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 5m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:3001</span></span></code></pre></div><blockquote><p>各系统永久生效的改法不同（<code>/etc/security/limits.conf</code>、systemd 的 <code>LimitNOFILE</code>、macOS 的 <code>launchctl limit</code>）。真要用几千并发时，建议<strong>边压边盯</strong> <code>ulimit -n</code> 和日志里的相关警告，别等报告出来才发现是压测机自己不够用。</p></blockquote><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>Python ≥ 3.11</strong>，先用 <code>python3 --version</code> 确认</li><li><strong>用虚拟环境</strong>：<code>python3 -m venv .venv</code> → 激活 → <code>pip install locust</code></li><li><strong>验证</strong>：<code>locust -V</code> 能打印版本就成功</li><li><strong>目录</strong>：脚本默认叫 <code>locustfile.py</code>，同目录的 <code>.py</code> 可以互相 <code>import</code>；脚本多了按包拆（<code>common/</code> + <code>my_locustfiles/</code>）</li><li><strong>找不到命令</strong>十有八九是虚拟环境没激活</li><li><strong>venv 是项目级的</strong>：换个项目要重新 <code>source</code>；想一次装好多项目复用，用 <code>pipx</code> 或共享 venv</li><li><strong>pipx 的环境是封闭的</strong>：脚本要 <code>import pandas</code>、<code>faker</code> 这类第三方库时，得 <code>pipx inject locust &lt;包&gt;</code>，或者干脆回到项目 venv</li><li><strong>压高并发前</strong>先 <code>ulimit -n</code> 看文件描述符上限，撞墙时 Concurrent 上不去、日志有警告</li></ul><p>环境好了，下一章写第一个压测脚本。</p>`,94)])])}const u=a(n,[["render",p]]);export{k as __pageData,u as default};
